export function tailText(text, budget) {
    const bytes = Buffer.from(text, "utf8");
    if (budget <= 0 || bytes.length === 0) {
        return "";
    }
    let total = 0;
    let start = bytes.length;
    // Walk code points from the end (Buffer indices are byte indices).
    for (let i = bytes.length - 1; i >= 0;) {
        // Find start of the code point ending at byte i.
        let cpStart = i;
        while (cpStart > 0 && (bytes[cpStart] & 0xc0) === 0x80) {
            cpStart--;
        }
        // Include any continuation bytes if cpStart landed mid-sequence.
        const len = i - cpStart + 1;
        if (total + len > budget) {
            break;
        }
        total += len;
        start = cpStart;
        i = cpStart - 1;
    }
    return bytes.subarray(start).toString("utf8");
}

