export function mapLimit(items, limit, work) {
    return new Promise((resolve, reject) => {
        if (!Number.isInteger(limit) || limit <= 0) {
            reject(new TypeError("limit must be a positive integer"));
            return;
        }
        if (!Array.isArray(items)) {
            reject(new TypeError("items must be an array"));
            return;
        }
        const results = new Array(items.length);
        let nextIndex = 0;
        let active = 0;
        let settled = false;
        let firstError = null;
        let running = false;

        function pump() {
            running = true;
            while (!settled && active < limit && nextIndex < items.length) {
                const index = nextIndex++;
                active++;
                let promise;
                try {
                    promise = work(items[index], index);
                } catch (err) {
                    observeError(err);
                    break;
                }
                Promise.resolve(promise).then(
                    (value) => {
                        results[index] = value;
                        active--;
                        if (settled) {
                            checkDrained();
                        } else {
                            pump();
                        }
                    },
                    (err) => {
                        active--;
                        observeError(err);
                    }
                );
            }
            running = false;
            checkDrained();
        }

        function observeError(err) {
            if (firstError === null) {
                firstError = err;
            }
            settled = true;
            checkDrained();
        }

        function checkDrained() {
            if (!running && active === 0 && firstError !== null) {
                reject(firstError);
            }
        }

        if (items.length === 0) {
            resolve([]);
            return;
        }
        pump();
    });
}

