            if (sawCR) {
                sawCR = false;
                if (ch === "\n") {
                    emit(pending); // CRLF counts once
                    pending = "";
                    continue;
                }
                emit(pending); // standalone CR delimited a line
                pending = "";
            }
            if (ch === "\n") {
                emit(pending);
                pending = "";
            } else if (ch === "\r") {
                sawCR = true; // may be CR or start of CRLF; defer
            } else {
                pending += ch;
            }
        }
    }

    return {
        write(chunk) {
            if (ended) {
                throw new TypeError("write after end");
            }
            feed(decoder.write(chunk));
        },
        end() {
            if (ended) { return; }
            ended = true;
            feed(decoder.end());
            if (sawCR) {
                sawCR = false;
