export function memoizeReport(load) {
    const values = new Map();
    return (tenant, query) => {
        const labels = Array.isArray(query?.labels) ? [...query.labels].sort() : [];
        const uniqueLabels = labels.filter((label, i) => i === 0 || label !== labels[i - 1]);
        const normalizedQuery = { labels: uniqueLabels, archived: query?.archived === true };
        const key = JSON.stringify([tenant, stableStringify(normalizedQuery)]);
        if (!values.has(key)) {
            const entry = Promise.resolve().then(() => load(tenant, normalizedQuery));
            entry.catch(() => { if (values.get(key) === entry) { values.delete(key); } });
            values.set(key, entry);
        }
        return values.get(key);
    };
}

