        this.generation = randomUUID();
        this.receipts.clear();
    }
    add(binding, before, after, outcome, output) {
        const receipt = {
            schema: 1,
            id: randomUUID(),
            generation: this.generation,
            root: binding.root,
            spec: { ...binding.spec },
            specDigest: executionSpecDigest(binding.spec),
            inputs: [...binding.inputs],
            before,
            after,
            outcome: { ...outcome },
