export function receiptFresh(before, after) {
    const beforeInputs = before.inputs ?? {};
    const afterInputs = after.inputs ?? {};
    if (before.head !== after.head) {
        return false;
    }
    const beforeKeys = Object.keys(beforeInputs).sort();
    const afterKeys = Object.keys(afterInputs).sort();
    if (beforeKeys.length !== afterKeys.length) {
        return false;
    }
    for (let i = 0; i < beforeKeys.length; i++) {
        if (beforeKeys[i] !== afterKeys[i]) {
            return false;
        }
        if (beforeInputs[beforeKeys[i]] !== afterInputs[afterKeys[i]]) {
            return false;
        }
    }
    return true;
}

