function stableInputs(inputs) {
    const keys = Object.keys(inputs).sort();
    return JSON.stringify(keys.map((k) => [k, inputs[k]]));
}

export function receiptFresh(before, after) {
    return before.head === after.head && stableInputs(before.inputs) === stableInputs(after.inputs);
}

