export function tailText(text, budget) {
    const bytes = Buffer.from(text, "utf8");
    if (!(budget >= 0) || !Number.isInteger(budget)) {
        throw new TypeError("budget must be a nonnegative integer");
    }
    if (budget === 0) return "";
    if (bytes.length <= budget) return text;
    // Walk backwards to find the largest suffix that fits the budget
    // without splitting a multi-byte UTF-8 sequence.
    let start = bytes.length - budget;
    while (start < bytes.length && (bytes[start] & 0xc0) === 0x80) {
        start++;
    }
    return bytes.subarray(start).toString("utf8");
}

