export function tailText(text, budget) {
    const buf = Buffer.from(text);
    if (budget <= 0) return "";
    if (budget >= buf.length) return text;
    let start = buf.length - budget;
    while (start > 0 && (buf[start] & 0xC0) === 0x80) start--;
    return buf.subarray(start, buf.length).toString("utf8");
}

