export function parseRecord(record) {
    const fields = [];
    let field = "";
    let i = 0;
    while (i < record.length) {
        const ch = record[i];
        if (ch === '"') {
            i++;
            let closed = false;
            while (i < record.length) {
                if (record[i] === '"') {
                    if (i + 1 < record.length && record[i + 1] === '"') {
                        field += '"';
                        i += 2;
                    } else {
                        closed = true;
                        i++;
                        break;
                    }
                } else {
                    field += record[i];
                    i++;
                }
            }
            if (!closed) {
                throw new Error("unterminated quote");
            }
            if (i < record.length && record[i] !== ',') {
                throw new Error("unexpected characters after closing quote");
            }
        } else if (ch === ',') {
            fields.push(field);
            field = "";
            i++;
        } else {
            if (i === 0 || record[i - 1] === ',') {
                // start of a field: ok, but a quote inside an unquoted field must throw
            }
            if (ch === '"') {
                throw new Error("quote inside unquoted field");
            }
            field += ch;
            i++;
        }
    }
    fields.push(field);
    return fields;
}

