                        field += '"';
                        i += 2;
                    } else {
                        closed = true;
                        i++;
                        break;
                    }
                } else {
                    field += record[i];
                    i++;
                }
            }
            if (!closed) {
                throw new Error('unterminated quote');
            }
            if (i < n && record[i] === ',') {
                fields.push(field);
                field = '';
                i++;
                continue;
            }
            if (i < n) {
                throw new Error('unexpected character after closing quote');
            }
            fields.push(field);
            field = '';
            i++;
            break;
        } else if (record[i] === '"') {
            throw new Error('quote inside unquoted field');
        } else if (record[i] === ',') {
            fields.push(field);
            field = '';
            i++;
        } else {
