export function canonicalKey(value) {
    const encode = (v) => {
        if (v === null) {
            return "0:null";
        }
        switch (typeof v) {
            case "string":
                // Length prefix keeps separators inside strings unambiguous.
                return "s" + v.length + ":" + v;
            case "number":
                return "n:" + String(v);
            case "boolean":
                return "b:" + String(v);
        }
        if (Array.isArray(v)) {
            // Arrays use index order, not lexicographic key order.
            return "a[" + v.map(encode).join(",") + "]";
        }
        const keys = Object.keys(v).sort();
        return "o{" + keys.map((k) => encode(k) + ":" + encode(v[k])).join(",") + "}";
    };
    return encode(value);
}

