export function tailText(text, budget) {
    if (!Number.isInteger(budget) || budget < 0) {
        throw new RangeError("budget must be a nonnegative integer");
    }
    if (budget === 0) return "";
    const bytes = Buffer.from(text, "utf8");
    if (bytes.length <= budget) return text;
    let total = 0;
    let start = bytes.length;
    while (start > 0) {
        let seqStart = start - 1;
        while (seqStart > 0 && (bytes[seqStart] & 0xC0) === 0x80) {
            seqStart--;
        }
        const b = bytes[seqStart];
        let len;
        if ((b & 0x80) === 0x00) len = 1;
        else if ((b & 0xE0) === 0xC0) len = 2;
        else if ((b & 0xF0) === 0xE0) len = 3;
        else if ((b & 0xF8) === 0xF0) len = 4;
        else break;
        if (start - seqStart !== len) break;
        if (total + len > budget) break;
        total += len;
        start = seqStart;
    }
    return bytes.subarray(start).toString("utf8");
}

