export function tailText(text, budget) {
    const chars = Array.from(text);
    let total = 0;
    let i = chars.length;
    while (i > 0) {
        const c = chars[i - 1];
        let len;
        const cp = c.codePointAt(0);
        if (cp < 0x80) len = 1;
        else if (cp < 0x800) len = 2;
        else if (cp < 0x10000) len = 3;
