export function createLines(emit) {
    let ended = false;
    let pendingCR = false;
    let carry = "";
    const decoder = new TextDecoder("utf-8", { stream: true });
    function feed(text, isEnd) {
        let i = 0;
        while (i < text.length) {
            if (pendingCR) {
                pendingCR = false;
                if (text[i] === "\n") {
                    i++;
                }
                emit(carry);
                carry = "";
                continue;
            }
            if (text[i] === "\r") {
                if (i + 1 < text.length) {
                    i++;
                    if (text[i] === "\n") i++;
                    emit(carry);
                    carry = "";
                } else if (isEnd) {
                    i++;
                    emit(carry);
                    carry = "";
                } else {
                    pendingCR = true;
                    i++;
                }
                continue;
            }
            if (text[i] === "\n") {
                i++;
                emit(carry);
                carry = "";
                continue;
            }
            let j = i;
            while (j < text.length && text[j] !== "\r" && text[j] !== "\n") j++;
