            i = j;
        }
    }
    return {
        write(chunk) {
            if (ended) {
                throw new Error("write after end");
            }
            if (!chunk || chunk.length === 0) {
                return;
            }
            feed(decoder.decode(chunk, { stream: true }), false);
        },
        end() {
            if (ended) {
                return;
            }
            ended = true;
            feed(decoder.decode(undefined, { stream: true }), true);
            if (pendingCR) {
                pendingCR = false;
                emit(carry);
                carry = "";
            }
            if (carry !== "") {
                emit(carry);
                carry = "";
            }
        },
    };
}

