export function normalizeQuery(query) {
    return { labels: [...new Set(query.labels)].sort(), archived: query.archived };
}

export function cacheKey(tenant, normalized) {
    return JSON.stringify([tenant, normalized.labels, normalized.archived]);
}

export function memoizeReport(load) {
    const values = new Map();
    return (tenant, query) => {
        const normalized = normalizeQuery(query);
        const key = cacheKey(tenant, normalized);
        if (!values.has(key)) {
            const freshQuery = normalizeQuery(query);
            let promise;
            try {
                promise = Promise.resolve(load(tenant, freshQuery));
            } catch (error) {
                promise = Promise.reject(error);
            }
            promise = promise.catch((error) => {
                if (values.get(key) === promise) { values.delete(key); }
                throw error;
            });
            values.set(key, promise);
        }
        return values.get(key);
    };
}

